# Manual idempotency tests (preserved outside AUTOGENERATED markers so the
# generator does not overwrite them on regeneration).
class ExitJson(Exception):
    def __init__(self, payload):
        self.payload = payload


class FailJson(Exception):
    def __init__(self, payload):
        self.payload = payload


class FakeModule:
    def exit_json(self, **kwargs):
        raise ExitJson(kwargs)

    def fail_json(self, **kwargs):
        raise FailJson(kwargs)


class FakeAPIPath:
    def __init__(self, client, segments=None):
        self.client = client
        self.segments = segments or []

    def __getitem__(self, key):
        return FakeAPIPath(self.client, self.segments + [key])

    def first(self):
        assert self.segments == ["protectedpaths", 7]
        return self.client.protected_path

    def patch(self, **payload):
        self.client.calls.append((self.segments[-1], payload))
        return {"result": "ok", **payload}


class FakeClient:
    def __init__(self, protected_path):
        self.protected_path = protected_path
        self.calls = []
        self.api = FakeAPIPath(self)

    def wait_for_task(self, task_id, timeout=300):
        raise AssertionError("No async task should be returned in these tests")


def make_resource(protected_path, **params):
    resource = protectedpath_streams.ProtectedpathStreams.__new__(protectedpath_streams.ProtectedpathStreams)
    defaults = {
        "protectedpath_id": 7,
        "action": "add_stream",
        "state": "present",
        "stream_id": None,
        "name": "test1_policy1",
        "target_exported_dir": "/data4",
        "protection_policy_id": "46",
        "remote_tenant_guid": "tenant-guid",
        "capabilities": "ASYNC_REPLICATION",
        "remote_target_id": None,
        "sync_interval": None,
        "lease_expiry_time": None,
        "sync_disconnect_time": None,
        "source_member_capabilities": None,
        "view_replication_enabled": True,
        "wait": True,
        "wait_timeout": 300,
    }
    defaults.update(params)
    resource.params = defaults
    resource.check_mode = False
    resource.module = FakeModule()
    resource.client = FakeClient(protected_path)
    return resource


def run_resource(resource):
    try:
        resource.run()
    except ExitJson as exc:
        return exc.payload
    raise AssertionError("resource did not exit")


class TestProtectedpathStreamsIdempotency:
    def test_adds_missing_stream(self):
        resource = make_resource({"id": 7, "replication_streams": []})

        result = run_resource(resource)

        assert result["changed"] is True
        assert resource.client.calls == [
            (
                "add_stream",
                {
                    "name": "test1_policy1",
                    "protection_policy_id": "46",
                    "target_exported_dir": "/data4",
                    "remote_tenant_guid": "tenant-guid",
                    "capabilities": "ASYNC_REPLICATION",
                    "view_replication_enabled": True,
                },
            )
        ]

    def test_noops_when_stream_exists(self):
        stream = {"id": 10, "name": "test1_policy1", "capabilities": "ASYNC_REPLICATION"}
        resource = make_resource({"id": 7, "replication_streams": [stream]})

        result = run_resource(resource)

        assert result["changed"] is False
        assert result["protectedpath_stream"] == stream
        assert resource.client.calls == []

    def test_modifies_capability_drift(self):
        stream = {"id": 10, "name": "test1_policy1", "capabilities": "SYNC_REPLICATION"}
        resource = make_resource({"id": 7, "replication_streams": [stream]})

        result = run_resource(resource)

        assert result["changed"] is True
        assert resource.client.calls == [("modify_member", {"stream_id": "10", "capabilities": "ASYNC_REPLICATION"})]

    def test_removes_existing_stream_for_absent_state(self):
        stream = {"id": 10, "name": "test1_policy1", "capabilities": "ASYNC_REPLICATION"}
        resource = make_resource({"id": 7, "replication_streams": [stream]}, state="absent")

        result = run_resource(resource)

        assert result["changed"] is True
        assert resource.client.calls == [("remove_stream", {"stream_id": "10"})]

    def test_noops_absent_when_stream_missing(self):
        resource = make_resource({"id": 7, "replication_streams": []}, state="absent")

        result = run_resource(resource)

        assert result["changed"] is False
        assert result["protectedpath_stream"] == {}
        assert resource.client.calls == []
